import{_ as s,o as a,c as e,a3 as t}from"./chunks/framework.DhF4LrUq.js";const k=JSON.parse('{"title":"Manage versions and tags","description":"Manage versions and tags - create the version, upload immutable builds with the CLI, tag them, archive, and revoke distribution.","frontmatter":{"description":"Manage versions and tags - create the version, upload immutable builds with the CLI, tag them, archive, and revoke distribution."},"headers":[],"relativePath":"how-to/console/versions-and-tags.md","filePath":"how-to/console/versions-and-tags.md"}'),n={name:"how-to/console/versions-and-tags.md"};function o(l,i,h,r,p,d){return a(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="manage-versions-and-tags" tabindex="-1">Manage versions and tags <a class="header-anchor" href="#manage-versions-and-tags" aria-label="Permalink to &quot;Manage versions and tags&quot;">​</a></h1><p>A version is the <code>7.12.0</code> line of your application; its artifacts — the immutable <code>.ipa</code> / <code>.apk</code> / <code>.aab</code> binaries — arrive by <a href="/shipperdog/snapshot/concepts/artifact-pipeline">upload</a> and never change. Version management lives in the CLI and API (the Console&#39;s application page shows the registry facts), so this guide walks both surfaces.</p><div class="tip custom-block"><p class="custom-block-title">Where the screens are</p><p>The Console&#39;s application detail page carries the registry&#39;s facts — bundle identifiers, ownership, audit trail. The version list and artifact inventories you drive from the <a href="/shipperdog/snapshot/how-to/automation/cli-reference">CLI</a>, which is also what your CI pipeline uses.</p></div><h2 id="create-a-version" tabindex="-1">Create a version <a class="header-anchor" href="#create-a-version" aria-label="Permalink to &quot;Create a version&quot;">​</a></h2><ol><li><p>Create the version with the API (an application-scoped call):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SHIPPERDOG_API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v1/applications/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APP_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/versions&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;versionName&quot;: &quot;7.12.0&quot;}&#39;</span></span></code></pre></div></li><li><p>Or let your pipeline name the version directly at upload — the CLI&#39;s <code>--version</code> flag takes the name (for example <code>7.12.0</code>) once the version exists; names need <code>--app</code> when several applications share the name.</p></li></ol><h2 id="upload-builds-to-the-version" tabindex="-1">Upload builds to the version <a class="header-anchor" href="#upload-builds-to-the-version" aria-label="Permalink to &quot;Upload builds to the version&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shipperdog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artifact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app-release.apk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> banking</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7.12.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --platform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> android</span></span></code></pre></div><ul><li>The platform is <code>ios</code> or <code>android</code>; the file may be an <code>.ipa</code>, <code>.apk</code>, or <code>.aab</code>.</li><li>Provenance flags (<code>--git-commit</code>, <code>--git-branch</code>, <code>--pipeline</code>, <code>--ci-run-url</code>, <code>--build-timestamp</code>) are optional and never fabricated — the <a href="/shipperdog/snapshot/how-to/automation/github-actions">GitHub Actions integration</a> fills them from the build context automatically.</li><li>The command waits for validation to settle by default: it exits <code>0</code> when the artifact is READY and <code>4</code> when validation rejected it, printing the failing stage.</li></ul><p>Large files (above 100 MiB by default) switch to a resumable upload session automatically.</p><h2 id="inspect-artifacts" tabindex="-1">Inspect artifacts <a class="header-anchor" href="#inspect-artifacts" aria-label="Permalink to &quot;Inspect artifacts&quot;">​</a></h2><ul><li><code>shipperdog artifact list banking</code> — one row per artifact slot across the application&#39;s versions; <code>--version 7.12.0</code> narrows it.</li><li><code>shipperdog artifact view &lt;artifactId&gt; --version 7.12.0 --app banking</code> — the full extraction and validation block: per-stage status, format verdict, provenance.</li><li><code>shipperdog artifact revalidate &lt;artifactId&gt; --version 7.12.0 --app banking</code> — re-runs validation on a FAILED or stalled artifact.</li></ul><h2 id="tag-versions" tabindex="-1">Tag versions <a class="header-anchor" href="#tag-versions" aria-label="Permalink to &quot;Tag versions&quot;">​</a></h2><p>Tags are short labels (<code>rc1</code>, <code>hotfix-candidate</code>) that make versions findable:</p><ol><li><p>Set the tags on a version — the write replaces the full set:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SHIPPERDOG_API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v1/applications/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APP_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/versions/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$VERSION_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/tags&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;tags&quot;: [&quot;rc1&quot;, &quot;qa-passed&quot;]}&#39;</span></span></code></pre></div></li><li><p>List by tag from the CLI:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shipperdog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> banking</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rc1</span></span></code></pre></div></li></ol><h2 id="archive-and-revoke-distribution" tabindex="-1">Archive and revoke distribution <a class="header-anchor" href="#archive-and-revoke-distribution" aria-label="Permalink to &quot;Archive and revoke distribution&quot;">​</a></h2><p>Two distinct end-of-life moves, both through the version API:</p><ul><li><strong>Archive</strong> (<code>POST .../versions/{id}/archive</code>) — the version leaves the working set. <code>shipperdog version list</code> shows DRAFT and ACTIVE versions by default; pass <code>--include archived,revoked</code> to widen.</li><li><strong>Revoke distribution</strong> (<code>POST .../versions/{id}/revoke-distribution</code>) — stronger: existing download links stop answering. A mandatory reason records why.</li></ul><div class="tip custom-block"><p class="custom-block-title">Tags are metadata, never a gate</p><p>A tag never decides who receives a build — releases and rings do. See <a href="/shipperdog/snapshot/how-to/console/rings-and-promotion">rings and promotion</a>.</p></div><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/automation/cli-reference">the CLI reference</a> · <a href="/shipperdog/snapshot/concepts/artifact-pipeline">artifact pipeline concepts</a> · <a href="/shipperdog/snapshot/how-to/console/releases">work with releases</a></p>`,19)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
